uint8_t ui_text_asset_normalize_size(uint8_t size)
{
    if (size <= 10U) {
        return 10U;
    }
    if (size <= 13U) {
        return 12U;
    }
    return 16U;
}

const ui_text_asset_t *ui_text_asset_find(const char *text, uint8_t size)
{
    if (text == NULL || text[0] == '\0') {
        return NULL;
    }
    uint8_t normalized = ui_text_asset_normalize_size(size);
    for (size_t i = sizeof(s_text_assets) / sizeof(s_text_assets[0]); i > 0; --i) {
        const ui_text_asset_t *asset = &s_text_assets[i - 1];
        if (asset->size == normalized && strcmp(asset->text, text) == 0) {
            return asset;
        }
    }
    return NULL;
}

bool ui_text_asset_has_cjk(const char *text)
{
    if (text == NULL) {
        return false;
    }
    const unsigned char *p = (const unsigned char *)text;
    while (*p != '\0') {
        if ((*p & 0xF0U) == 0xE0U) {
            uint32_t cp = ((uint32_t)(p[0] & 0x0FU) << 12) |
                          ((uint32_t)(p[1] & 0x3FU) << 6) |
                          (uint32_t)(p[2] & 0x3FU);
            if (cp >= 0x4E00U && cp <= 0x9FFFU) {
                return true;
            }
            p += p[1] != '\0' && p[2] != '\0' ? 3 : 1;
        } else {
            ++p;
        }
    }
    return false;
}
